package Controlstatement;

public class dowhile1 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		
		
		    int a=2;
		    
		    while(a>=2)
		    {
		    	
		    	System.out.println("The A inside while loop value is : "+a);
		    	a--;
		    }
		    
		    System.out.println("The A value is : "+a);
		    System.out.println("Hello");
		    
		    
		  /*  ==>Following syntax For do while ::
                
                do
                  { 
                           ---------    //Java Statement
                           ---------
                   }while(exp) */
		   
		    
		    int b=2;
		   
		   do 
		    {  
			   
			   System.out.println("The B value is inside do loop" +b);
			   b--;
			   
			   
		   }while(b>=2);
		   
		    System.out.println("The  after do while value of b is : "+b);
		    
		    
		    
		    
		    
		    
	}

}
